  requires n == len(s1) and m == len(s2) and k == len(s3)
  requires n >= 0 and m >= 0 and k >= 0
  ensures r >= 0
  ensures r == lcs3(s1, s2, s3)
  ensures r <= n and r <= m and r <= k
spec fun lcs3(a: seq, b: seq, c: seq): int
  decreases len(a) + len(b) + len(c)
= if len(a) == 0 then 0 else if len(b) == 0 then 0 else if len(c) == 0 then 0 else if a[len(a)-1] == b[len(b)-1] and b[len(b)-1] == c[len(c)-1] then lcs3(a[0..len(a)-1], b[0..len(b)-1], c[0..len(c)-1]) + 1 else if lcs3(a[0..len(a)-1], b, c) >= lcs3(a, b[0..len(b)-1], c) then if lcs3(a[0..len(a)-1], b, c) >= lcs3(a, b, c[0..len(c)-1]) then lcs3(a[0..len(a)-1], b, c) else lcs3(a, b, c[0..len(c)-1]) else if lcs3(a, b[0..len(b)-1], c) >= lcs3(a, b, c[0..len(c)-1]) then lcs3(a, b[0..len(b)-1], c) else lcs3(a, b, c[0..len(c)-1])
{
  var w: int := (m + 1) * (k + 1);
